export const CATALOG_SKILLS: readonly MetaSkill[] = [{"id":"data_flows/cqrs_flow","title":"CQRS Command/Query Data Flow Pattern","category":"data_flow","tags":["data_flow","cqrs","architecture"],"summary":"读写责任分离数据流模式：写命令 (Command) 与读查询 (Query) 完全解耦，防止领域写逻辑与多维读查询逻辑污染。","data_flow_diagram":"Client -> Command -> CommandHandler -> DomainEntity -> Repository (Write)\nClient -> Query -> QueryHandler -> DTO -> View (Read)","data_schema":{"CreateOrderCommand":"{ order_id: string, item_ids: string[], user_id: string }","OrderReadDTO":"{ order_id: string, status: string, total_price: number }"},"example_cases":[{"title":"Command Handler Pattern","code_snippet":"class CreateOrderCommandHandler:\n    async def handle(self, cmd: CreateOrderCommand) -> str:\n        order = Order.create(cmd.user_id, cmd.item_ids)\n        await self.repo.save(order)\n        return order.id"}],"agent_instructions":["1. 确认请求是写操作 (Command) 还是读操作 (Query)。","2. 禁止在 CommandHandler 中直接拼接复杂的读视图 SQL；禁止在 QueryHandler 中触发状态修改。"]},{"id":"data_models/standard_dto","title":"Standard DTO & Domain Entity Separation Model","category":"data_model","tags":["data_model","dto","entity","validation"],"summary":"标准数据模型隔离范式：区分 API 传输对象 (DTO) 与 核心业务实体 (Domain Entity)，隔离 API 变更对数据库的破坏。","data_schema":{"UserRegistrationRequestDTO":"Pydantic BaseModel with strict validation (email, password strength)","UserEntity":"Pure dataclass or DDD Aggregate root representing User business state"},"example_cases":[{"title":"DTO to Entity Mapping","code_snippet":"class UserDTO(BaseModel):\n    email: EmailStr\n    username: str\n\n    def to_entity((self) -> UserEntity:\n        return UserEntity(id=generate_id(), email=self.email, username=self.username)"}],"agent_instructions":["1. 永远不要将数据库 ORM 模型直接露给 Controller 或 API 响应层。","2. 使用轻量转换器 `.to_entity()` 实现 DTO 与 Entity 的无损映射。"]},{"id":"meta_skills/auth_factory_skill","title":"Auth Factory Meta-Skill (OAuth2 & JWT Factory)","category":"meta_skill","tags":["meta_skill","auth","jwt","oauth2"],"summary":"标准用户鉴权类 Skill 案例包：包含身份令牌签发、OAuth2 钩子与 AuthAdapterSlot 关联能力。","data_flow_diagram":"Client -> AuthRoute -> AuthFactory -> AuthAdapterSlot -> JWT/OAuthProvider","data_schema":{"TokenPayload":"{ sub: string, exp: number, roles: string[] }","AuthResponse":"{ access_token: string, token_type: 'bearer' }"},"example_cases":[{"title":"Auth Slot Adapter Implementation","code_snippet":"class JWTAuthAdapter(BaseAuthAdapterSlot):\n    def verify_token(self, token: str) -> TokenPayload:\n        return jwt.decode(token, SECRET_KEY, algorithms=['HS256'])"}],"agent_instructions":["1. 当用户需要为系统加入身份鉴权时，优先调用 AuthFactory 及其 Slot 接口。","2. 将 JWT 密匙与敏感配置移至环境变量处理。"]},{"id":"philosophies/clean_boundary","title":"Clean Architectural Boundary & Anti-Entropy Philosophy","category":"philosophy","tags":["philosophy","anti-entropy","clean-code"],"summary":"整洁架构边界与防代码爆炸核心哲学：限制单文件 300 行上限、单向依赖箭头与 Slot 插槽隔离，确保项目不会随着体积增加而演化为不可维护的散沙。","example_cases":[{"title":"Boundary Violation vs Clean Isolation","code_snippet":"# BAD (Boundary Violation):\n# Router -> DB直接查询\n\n# GOOD (Clean Boundary):\n# Router -> Service -> InterfaceSlot -> DBAdapter"}],"agent_instructions":["1. 随时保持文件小于 300 行，超过时提示用户拆解出独立子模块。","2. 当需要引入第三方库时，检查该库对应的 `library_dict` 摆放规则。"]},{"id":"meta_skills/dsh_plugin_paradigm","title":"DeepSeek Harness Plugin Development Paradigm (DSH/Cordis 插件通用范式)","category":"meta_skill","tags":["meta_skill","dsh","cordis","plugin","deepseek-harness"],"summary":"构建 DeepSeek Harness (Cordis) 插件的一等范式：宿主/客户端双平面、工具/服务/事件/UI 插槽、注入纪律、JSON-only 边界、可逆副作用、正确挂载平面，以及会话级动态插件与部署级 dsh.bundle 两条加载路径。","data_flow_diagram":"Profile/Preset mount -> apply(ctx) -> register tools/services/events/UI\nModel step -> tool call -> execute(args, exec) -> canonical lossless JSON\nTool result -> render(args, value) -> ContentBlock[] -> back to the agent loop\nStop/update -> disposers unwind -> every contribution removed","data_schema":{"PluginExports":"{ name: string, inject?: string[], Config?: z.object, apply(ctx, config?) }","ToolDefinition":"{ name, description, parameters: { [k]: { type, required? } }, output: { schema, render(args,value)->ContentBlock[] }, execute(args, exec)->Promise<JSON> }","ToolRunContext":"{ signal: AbortSignal, agent?, deferContext?, concludeTurn? }","ClientSlot":"slots.inject(target, () => slots.register({ name, key? }, (props) => ReactElement))","DeploymentLayer":"package.json { dsh: { bundle: { patch: './cordis.patch.yml' } } } -> dsh plugin add auto-appends to dsh.profile.bundles"},"example_cases":[{"title":"Read-only model tool (host half)","code_snippet":"return {\n  name: 'my-plugin',\n  inject: ['tools'],\n  apply(ctx) {\n    ctx.tools.register(defineTool({\n      name: 'my_tool',\n      description: 'Inspect one item.',\n      parameters: { id: { type: 'string', required: true, description: 'item id' } },\n      output: {\n        schema: { type: 'object', additionalProperties: true, properties: { id: { type: 'string' } } },\n        render(_a, v) { return [{ type: 'text', text: JSON.stringify(v) }] },\n      },\n      execute(args) { return Promise.resolve({ id: args.id }) },\n    }))\n  },\n}"},{"title":"Explicit profile-layer plugin (dsh.bundle)","code_snippet":"// package.json\n{ \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } } }\n\n// cordis.patch.yml (ships in the npm package)\n- insert:\n    - id: tool-my-plugin\n      name: my-plugin"},{"title":"Client slot UI (browser half)","code_snippet":"return {\n  apply(ctx) {\n    const slots = ctx.get('slots')\n    if (slots === undefined) return\n    slots.inject('tool.view.cordis', () => slots.register(\n      { name: 'tool.view.cordis', key: 'self' },\n      (props) => React.createElement('div', null, String(props.packageId)),\n    ))\n  },\n}"}],"agent_instructions":["1. 硬依赖用 inject 声明（inject: ['tools']），可选服务一律 ctx.get(name) 并判空；未声明就访问 ctx.x 会被 Guard 拒绝。","2. 工具用 defineTool：参数用 DSL（每属性内联 required: true），输出 { schema, render }，execute 只返回 lossless JSON（缺省字段省略，禁止 undefined）。","3. 每个副作用必须可逆：ctx.on / ctx.effect / 持有 disposer；插件停止或更新后不留残余。","4. 跨边界只传 JSON：不 JSON.stringify/structuredClone Service、Event、Session、Tool 等活对象，只读所需叶字段。","5. 服务发布行必须置于 isolate realm 内；纯消费工具行平铺放 preset；绝不编辑官方 preset（复制到用户根后改副本）。","6. 会话级临时能力用动态插件（cordis_define + cordis_run，宿主侧 harness.defineTool/registerTool，动态包禁止 import）；部署级插件在 package.json 声明 dsh.bundle，dsh plugin add 自动加入 dsh.profile.bundles 层。"]}];